<script setup lang="ts">
import {defineAsyncComponent,reactive} from 'vue'
import {useTaskPage} from '../hooks/useTaskPage'
import {taskStates,time} from '../shared/types'
const Schedule=defineAsyncComponent(()=>import('./TaskSchedule.vue'))
const props=defineProps<{level:number}>(),vm=reactive(useTaskPage(props.level))
</script>
<template><a-card :title="(level===1?'公司':'项目')+'核查任务'"><template #extra><a-space><a-button @click="vm.load" :loading="vm.loading">刷新</a-button><a-button v-if="vm.can('quality-task','save')" type="primary" @click="vm.start()">新建任务</a-button></a-space></template>
 <a-alert v-if="vm.error" type="error" :message="vm.error" show-icon /><a-space wrap style="margin:16px 0"><a-select v-model:value="vm.projectId" :options="vm.projects.map(p=>({value:p.id,label:p.name}))" placeholder="全部业务项目" allow-clear style="width:230px" /><a-select v-model:value="vm.status" :options="Object.entries(taskStates).map(([value,label])=>({value:Number(value),label}))" placeholder="全部状态" allow-clear style="width:160px" /><a-input-search v-model:value="vm.name" placeholder="任务名称" @search="vm.search" /></a-space>
 <a-table :data-source="vm.rows" :loading="vm.loading" row-key="id" :pagination="{current:vm.current,total:vm.total,pageSize:20,showSizeChanger:false}" :scroll="{x:'max-content'}" @change="(p:{current?:number})=>{vm.current=p.current||1;vm.load()}">
 <a-table-column title="任务名称" data-index="taskName" /><a-table-column title="业务项目" data-index="projectName" /><a-table-column title="模板" data-index="templateName" /><a-table-column title="类型" key="type"><template #default="{record}">{{record.taskType===1?'临时任务':'固定任务'}}</template></a-table-column><a-table-column title="状态" key="status"><template #default="{record}"><a-tag :color="record.taskStatus===1?'blue':'default'">{{taskStates[record.taskStatus]}}</a-tag></template></a-table-column><a-table-column title="创建时间" key="time"><template #default="{record}">{{time(record.createTime)}}</template></a-table-column>
 <a-table-column title="操作" key="actions"><template #default="{record}"><a-space><a-button type="link" @click="vm.start(record,true)">详情</a-button><a-button type="link" @click="vm.showPlan(record)">作业计划</a-button><template v-if="record.taskStatus===0"><a-button v-if="vm.can('quality-task','save')" type="link" @click="vm.start(record)">编辑</a-button><a-popconfirm v-if="vm.can('quality-task','issue')" title="确认下发？下发后不能修改。" @confirm="vm.act(record,'issue')"><a-button type="link">下发</a-button></a-popconfirm><a-popconfirm v-if="vm.can('quality-task','delete')" title="删除此任务？" @confirm="vm.act(record,'delete')"><a-button danger type="link">删除</a-button></a-popconfirm></template><a-popconfirm v-if="[0,1].includes(record.taskStatus)&&vm.can('quality-task','close')" title="关闭任务并停止后续作业计划？" @confirm="vm.act(record,'close')"><a-button type="link" danger>关闭</a-button></a-popconfirm></a-space></template></a-table-column></a-table>
 <a-drawer v-model:open="vm.open" :title="vm.readonly?'任务详情':vm.form.id?'编辑任务':'新建任务'" width="820"><a-alert v-if="vm.error" type="error" :message="vm.error" show-icon /><a-form layout="vertical" :model="vm.form" :disabled="vm.readonly" @finish="vm.save">
 <a-form-item label="任务名称" name="taskName" :rules="[{required:true,message:'请输入任务名称'}]"><a-input v-model:value="vm.form.taskName" :maxlength="128" /></a-form-item><a-form-item label="业务项目" name="projectId" :rules="[{required:true,message:'请选择业务项目'}]"><a-select v-model:value="vm.form.projectId" :options="vm.projects.map(p=>({value:p.id,label:p.name}))" :disabled="!!vm.form.id" /></a-form-item><a-form-item label="任务模板" name="templateId" :rules="[{required:true,message:'请选择模板'}]"><a-select v-model:value="vm.form.templateId" :options="vm.templates.map(t=>({value:t.id,label:t.name}))" @change="vm.selectTemplate" /></a-form-item>
 <a-divider orientation="left">条线核查人</a-divider><a-form-item v-for="line in vm.lines" :key="line.id" :label="line.name"><a-select :value="vm.form.lineAssignees.find(a=>a.subjectParentId===line.id)?.inspectorId" :options="vm.people.map(p=>({value:p.id,label:p.name}))" show-search option-filter-prop="label" @change="(v:unknown)=>vm.setAssignee(line.id,v)" /></a-form-item>
 <a-collapse v-if="vm.form.configItems?.length"><a-collapse-panel key="deduct" header="检查项与扣分规则"><a-form-item v-for="item in vm.form.configItems" :key="item.configId" :label="vm.snapshots.find(s=>s.configId===item.configId)?.contentName"><a-textarea v-model:value="item.deductionStandard" /></a-form-item></a-collapse-panel></a-collapse>
 <Schedule :form="vm.form" :readonly="vm.readonly" /><a-form-item label="备注" style="margin-top:20px"><a-textarea v-model:value="vm.form.remark" /></a-form-item><a-button v-if="!vm.readonly" type="primary" html-type="submit" :loading="vm.saving">保存任务</a-button></a-form></a-drawer>
 <a-drawer v-model:open="vm.planOpen" title="作业计划" width="800"><a-table :data-source="vm.plan" row-key="id"><a-table-column title="生成时间" key="time"><template #default="{record}">{{time(record.scheduledTime)}}</template></a-table-column><a-table-column title="周期开始" key="start"><template #default="{record}">{{time(record.cycleStartTime)}}</template></a-table-column><a-table-column title="周期结束" key="end"><template #default="{record}">{{time(record.cycleEndTime)}}</template></a-table-column><a-table-column title="状态" key="status"><template #default="{record}">{{({0:'未下发',1:'待生成',2:'已生成',3:'已关闭'} as Record<number,string>)[record.status]}}</template></a-table-column></a-table></a-drawer>
 </a-card></template>
